export type MarkdownEditorContextValue = {
  engine: MarkdownEditorEngine | null;
  disabled: boolean;
  readOnly: boolean;
  /** Formatting is possible: the engine is mounted, enabled, writable and is the visible editor. */
  editable: boolean;
  labels: MarkdownEditorLabels;
  source: boolean;
  markdown: string;
  sourceRequired: boolean;
  isUrlAllowed: MarkdownUrlPolicy;
  setSource: (source: boolean) => void;
  setMarkdown: (value: string) => void;
  canUpload: boolean;
  uploads: MarkdownImageUpload[];
  upload: (files: File[], position?: number) => void;
  retryUpload: (id: string) => void;
  removeUpload: (id: string) => void;
  uploadError: string | null;
};

export const MarkdownEditorContext = createContext<MarkdownEditorContextValue | null>(null);

export function useMarkdownEditor() {
  const context = useContext(MarkdownEditorContext);
  if (!context) throw new Error("Markdown editor parts require a MarkdownEditor parent.");
  return context;
}

const unmountedSnapshot: MarkdownEditorSnapshot = {
  marks: { bold: false, italic: false, strike: false, code: false },
  blocks: { bulletList: false, orderedList: false, taskList: false, blockquote: false, codeBlock: false },
  heading: null,
  link: null,
  canUndo: false,
  canRedo: false,
  focused: false,
  formattable: false,
  inlineOnly: false,
  isEmpty: true,
  sourceRequired: false,
};
const subscribeNothing = () => () => {};
const readUnmounted = () => unmountedSnapshot;

export function useEngineSnapshot(engine: MarkdownEditorEngine | null): MarkdownEditorSnapshot {
  return useSyncExternalStore(engine?.subscribe ?? subscribeNothing, engine?.getSnapshot ?? readUnmounted, readUnmounted);
}

export function useMarkdownEditorSnapshot(): MarkdownEditorSnapshot {
  return useEngineSnapshot(useMarkdownEditor().engine);
}

"use client";

import { GripVerticalIcon } from "lucide-react";
import { type RefObject, useEffect, useRef, useState } from "react";
import { useSkinIcon } from "@/components/control-ui/skin-provider";
import { Button } from "@/components/control-ui/ui/button";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { useMarkdownEditor } from "../context";

type BlockHandle = { position: number; top: number; visible: boolean; glide: boolean };

/** Hiding keeps the last place, so the handle fades out where it was instead of jumping first. */
function conceal(current: BlockHandle | null): BlockHandle | null {
  return current?.visible ? { ...current, visible: false, glide: false } : current;
}

/** The gutter sits outside every block, so the pointer's x is clamped into the text column before the hit test. */
function textColumnPoint(element: HTMLElement, point: { x: number; y: number }) {
  const rect = element.getBoundingClientRect();
  const style = getComputedStyle(element);
  const gutter = Number.parseFloat(style.paddingInlineStart);
  const x = style.direction === "rtl" ? Math.min(point.x, rect.right - gutter) : Math.max(point.x, rect.left + gutter);
  return { x, y: point.y };
}

export function MarkdownEditorDragHandle({ container }: { container: RefObject<HTMLDivElement | null> }) {
  const GripVerticalGlyph = useSkinIcon("gripVertical", GripVerticalIcon);
  const { engine, editable, labels } = useMarkdownEditor();
  const [block, setBlock] = useState<BlockHandle | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const [pointerSelection, setPointerSelection] = useState(false);
  const [lifted, setLifted] = useState(false);
  const button = useRef<HTMLButtonElement>(null);
  const dragging = useRef(false);
  const preview = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const surface = container.current;
    if (!engine || !surface || !editable) return;
    const { blocks } = engine;
    let frame = 0;
    let pointer: { x: number; y: number } | null = null;
    function show(start: number | null) {
      const rect = start === null ? null : blocks.rect(start);
      if (start === null || !rect || !surface) return;
      const top = rect.top - surface.getBoundingClientRect().top + surface.scrollTop;
      setBlock((current) =>
        current?.visible && current.position === start && current.top === top
          ? current
          : { position: start, top, visible: true, glide: current?.visible === true },
      );
    }
    function showAtPointer() {
      if (pointer && engine) show(blocks.at(textColumnPoint(engine.element, pointer)));
    }
    function track(event: MouseEvent) {
      if (dragging.current || button.current?.contains(event.target instanceof Node ? event.target : null)) return;
      pointer = { x: event.clientX, y: event.clientY };
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        showAtPointer();
      });
    }
    function engineChanged() {
      if (dragging.current) return;
      if (document.activeElement === button.current) show(blocks.atSelection());
      else if (pointer) showAtPointer();
      else if (engine?.getSnapshot().focused) show(blocks.atSelection());
      else setBlock(conceal);
    }
    function keyboardUsed() {
      pointer = null;
      setPointerSelection(false);
    }
    function hide() {
      cancelAnimationFrame(frame);
      frame = 0;
      pointer = null;
      if (!dragging.current && document.activeElement !== button.current) setBlock(conceal);
    }
    surface.addEventListener("mousemove", track);
    surface.addEventListener("mouseleave", hide);
    surface.addEventListener("keydown", keyboardUsed);
    const unsubscribe = engine.subscribe(engineChanged);
    return () => {
      cancelAnimationFrame(frame);
      unsubscribe();
      surface.removeEventListener("mousemove", track);
      surface.removeEventListener("mouseleave", hide);
      surface.removeEventListener("keydown", keyboardUsed);
      blocks.endDrag();
      preview.current?.remove();
      preview.current = null;
      dragging.current = false;
    };
  }, [engine, container, editable]);

  if (!engine || !editable) return null;
  const { blocks } = engine;
  const position = block ? block.position : blocks.atSelection();

  function endDrag() {
    blocks.endDrag();
    dragging.current = false;
    setLifted(false);
    preview.current?.remove();
    preview.current = null;
  }

  return (
    <>
      <Button
        ref={button}
        type="button"
        variant="ghost"
        size="xs"
        iconOnly
        data-markdown-drag-handle=""
        data-visible={block?.visible ? "" : undefined}
        data-glide={block?.glide ? "" : undefined}
        data-pointer-selection={pointerSelection ? "" : undefined}
        data-lifted={lifted ? "" : undefined}
        aria-label={labels.dragHandle}
        aria-description={labels.dragHandleDescription}
        title={labels.dragHandleHint}
        draggable
        style={{
          translate: block ? `0 ${block.top}px` : undefined,
          "--cui-button-background": "transparent",
          "--cui-button-hover-background": "transparent",
          "--cui-button-press-background": "transparent",
          "--cui-button-shadow": "0 0 transparent",
          "--cui-button-hover-shadow": "0 0 transparent",
        }}
        onClick={() => {
          if (position !== null) blocks.select(position);
        }}
        onPointerDown={() => {
          setPointerSelection(true);
          if (position !== null) blocks.prepareDrag(position);
        }}
        onPointerUp={() => {
          if (!dragging.current) blocks.endDrag();
        }}
        onKeyDown={(event) => {
          if (!event.altKey || !["ArrowUp", "ArrowDown"].includes(event.key) || position === null) return;
          event.preventDefault();
          const direction = event.key === "ArrowUp" ? -1 : 1;
          if (blocks.move(position, direction) !== null) setAnnouncement(labels.blockMoved(direction === -1 ? "up" : "down"));
        }}
        onDragStart={(event) => {
          const drag = position === null ? null : blocks.startDrag(position, event.dataTransfer);
          if (!drag) {
            event.preventDefault();
            return;
          }
          dragging.current = true;
          setLifted(true);
          const ghost = drag.preview;
          if (!ghost) return;
          preview.current?.remove();
          container.current?.append(ghost.element);
          preview.current = ghost.element;
          const frame = ghost.element.getBoundingClientRect();
          const anchor = ghost.anchor.getBoundingClientRect();
          ghost.element.toggleAttribute("data-clipped", ghost.element.scrollHeight > ghost.element.clientHeight);
          event.dataTransfer.setDragImage(
            ghost.element,
            Math.max(0, anchor.left - frame.left + event.clientX - drag.origin.left),
            Math.max(0, anchor.top - frame.top + event.clientY - drag.origin.top),
          );
        }}
        onDragEnd={() => {
          endDrag();
          setBlock(conceal);
        }}
      >
        <GripVerticalGlyph aria-hidden="true" />
      </Button>
      <LiveStatus message={announcement} />
    </>
  );
}

export type DragPreview = { element: HTMLDivElement; anchor: HTMLElement };

/** A list item takes its marker and indent from its list, so the copy keeps a shallow list around it. */
export function createDragPreview(nodes: readonly HTMLElement[], contentClass: string): DragPreview | null {
  const [first] = nodes;
  if (!first) return null;
  const preview = document.createElement("div");
  preview.className = contentClass;
  preview.dataset.markdownDragPreview = "";
  preview.setAttribute("aria-hidden", "true");
  let remainingNodes = 80;
  let remainingText = 2000;
  function clonePreview(source: Node): Node {
    remainingNodes--;
    const clone = source.cloneNode(false);
    if (clone instanceof HTMLElement) {
      clone.classList.remove("ProseMirror-selectednode");
      clone.removeAttribute("id");
    }
    if (clone instanceof Text) {
      clone.data = clone.data.slice(0, remainingText);
      remainingText -= clone.data.length;
    }
    for (const child of source.childNodes) {
      if (remainingNodes <= 0 || remainingText <= 0) break;
      clone.appendChild(clonePreview(child));
    }
    return clone;
  }
  const list = first.localName === "li" ? first.parentElement?.cloneNode(false) : null;
  const parent = list instanceof HTMLElement ? list : preview;
  if (parent !== preview) {
    parent.removeAttribute("id");
    preview.append(parent);
  }
  const width = `${first.getBoundingClientRect().width}px`;
  for (const node of nodes) {
    if (remainingNodes <= 0 || remainingText <= 0) break;
    const clone = clonePreview(node);
    if (clone instanceof HTMLElement) clone.style.inlineSize = width;
    parent.append(clone);
  }
  const anchor = parent.firstElementChild;
  if (!(anchor instanceof HTMLElement)) return null;
  return { element: preview, anchor };
}

import type { DragPreview } from "./drag/drag-preview";
import type { MarkdownImage } from "./uploads";

export type MarkdownMark = "bold" | "italic" | "strike" | "code";
export type MarkdownBlockType = "bulletList" | "orderedList" | "taskList" | "blockquote" | "codeBlock";
export type MarkdownHeadingLevel = 1 | 2 | 3 | 4 | 5 | 6;
export const markdownHeadingLevels: readonly MarkdownHeadingLevel[] = [1, 2, 3, 4, 5, 6];

export type MarkdownBlockCommand =
  | { type: "paragraph" }
  | { type: "heading"; level: MarkdownHeadingLevel }
  | { type: MarkdownBlockType }
  | { type: "horizontalRule" }
  | { type: "table" };

export type MarkdownTextRange = { from: number; to: number };
export type MarkdownMention = { label: string; href: string };

export type MarkdownEditorSnapshot = {
  marks: Readonly<Record<MarkdownMark, boolean>>;
  blocks: Readonly<Record<MarkdownBlockType, boolean>>;
  heading: MarkdownHeadingLevel | null;
  link: string | null;
  canUndo: boolean;
  canRedo: boolean;
  focused: boolean;
  /** A non-blank text selection outside code: what the bubble menu formats. */
  formattable: boolean;
  inlineOnly: boolean;
  isEmpty: boolean;
  /** The document holds Markdown this engine would lose, so only its source can be edited. */
  sourceRequired: boolean;
};

export type MarkdownTextBeforeCaret = { text: string; from: number; to: number };

export type MarkdownBlockDrag = { preview: DragPreview | null; origin: DOMRect };

/** A block is addressed by the document position it starts at; the deepest list item is its own block. Never moves focus. */
export type MarkdownBlocks = {
  at: (point: { x: number; y: number }) => number | null;
  atSelection: () => number | null;
  rect: (block: number) => DOMRect | null;
  select: (block: number) => void;
  /** Swaps the block with its neighbour, selects it, and returns where it now starts. */
  move: (block: number, direction: -1 | 1) => number | null;
  /** Called on pointer down so the first drag frame does no serialization work. */
  prepareDrag: (block: number) => void;
  startDrag: (block: number, transfer: DataTransfer) => MarkdownBlockDrag | null;
  endDrag: () => void;
};

export type MarkdownTableAxis = "row" | "column";
export type MarkdownColumnAlign = "left" | "center" | "right";
export type MarkdownTableTarget = { table: HTMLTableElement; row: number; column: number };

/** The header is row 0 and never moves; `select` and `move` keep focus on their caller, the edits focus the editor. */
export type MarkdownTables = {
  caret: () => MarkdownTableTarget | null;
  select: (table: HTMLTableElement, axis: MarkdownTableAxis, index: number) => void;
  move: (table: HTMLTableElement, axis: MarkdownTableAxis, from: number, to: number) => boolean;
  insert: (table: HTMLTableElement, axis: MarkdownTableAxis, index: number, side: "before" | "after") => void;
  remove: (table: HTMLTableElement, axis: MarkdownTableAxis, index: number) => void;
  align: (table: HTMLTableElement, column: number, align: MarkdownColumnAlign) => void;
  /** Adds a last row or column and puts the caret in its first new cell. */
  append: (table: HTMLTableElement, axis: MarkdownTableAxis) => void;
};

/** Upload placeholders live beside the Markdown, never in it, until their image arrives. */
export type MarkdownUploadPlaceholders = {
  insert: (id: string, name: string, at?: number) => void;
  complete: (id: string, image: Required<Pick<MarkdownImage, "url" | "alt">> & Pick<MarkdownImage, "title">) => void;
  remove: (id: string) => void;
  has: (id: string) => boolean;
};

/** Parts reach editors only through this contract, so every part works with every alternative; commands focus the editor first. */
export type MarkdownEditorEngine = {
  readonly element: HTMLElement;
  readonly sourceView: "editor" | "textarea";
  /** Calls the listener after every document, selection, focus or editability change. */
  subscribe: (listener: () => void) => () => void;
  getSnapshot: () => MarkdownEditorSnapshot;
  /** Runs for document changes the user makes, never for `setMarkdown`. */
  onChange: (listener: (markdown: string) => void) => () => void;
  getMarkdown: () => string;
  /** Replaces the document from outside and starts a fresh undo history; does nothing when the Markdown is already current. */
  setMarkdown: (markdown: string) => void;
  setEditable: (editable: boolean) => void;
  focus: () => void;
  undo: () => void;
  redo: () => void;
  toggleMark: (mark: MarkdownMark) => void;
  toggleBlock: (block: MarkdownBlockType) => void;
  setHeading: (level: MarkdownHeadingLevel | null) => void;
  setLink: (href: string | null) => void;
  insertImage: (image: { src: string; alt: string }) => void;
  selectionRect: () => DOMRect | null;
  /** Null wherever a trigger cannot start: unfocused, a selection, code, or a link. */
  textBeforeCaret: () => MarkdownTextBeforeCaret | null;
  caretRect: () => DOMRect | null;
  replaceWithBlock: (range: MarkdownTextRange, block: MarkdownBlockCommand) => void;
  replaceWithMention: (range: MarkdownTextRange, mention: MarkdownMention) => void;
  positionAt: (point: { x: number; y: number }) => number | null;
  readonly uploads: MarkdownUploadPlaceholders;
  readonly blocks: MarkdownBlocks;
  readonly tables: MarkdownTables;
};

"use client";

import { type ComponentProps, type CSSProperties, useEffect, useEffectEvent, useMemo, useRef, useState } from "react";
import type { MarkdownEditorKnobStyle } from "@/components/control-ui/knob-contracts/markdown-editor-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { defaultMarkdownEditorLabels, MarkdownEditorContext, type MarkdownEditorLabels, useEngineSnapshot } from "./context";
import type { MarkdownEditorEngine } from "./engine";
import { type MarkdownImageUploader, useImageUploads } from "./uploads";
import { type MarkdownUrlPolicy, persistentUrlPolicy } from "./url-policy";

export type MarkdownEditorStatus = { isEmpty: boolean; hasPendingUploads: boolean };
export type MarkdownEditorRootProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "style"> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (markdown: string) => void;
  disabled?: boolean;
  /** Shows the content without letting it change; the Markdown source stays viewable. */
  readOnly?: boolean;
  /** Replaces any of the editor's built-in strings, for every part at once. */
  labels?: Partial<MarkdownEditorLabels>;
  onUploadImage?: MarkdownImageUploader;
  maxImageBytes?: number;
  onStatusChange?: (status: MarkdownEditorStatus) => void;
  /** Which link and image URLs the editor keeps; defaults to URLs that survive a reload. Read once, when the editor mounts. */
  isUrlAllowed?: MarkdownUrlPolicy;
  style?: CSSProperties & MarkdownEditorKnobStyle;
};

export type MarkdownEditorContentProps = Omit<ComponentProps<"div">, "children"> & {
  label: string;
  placeholder?: string;
  autoFocus?: boolean;
};

const filesOf = (transfer: DataTransfer | null) => Array.from(transfer?.files ?? []);

export function MarkdownEditorRoot({
  engine,
  value,
  defaultValue = "",
  onValueChange,
  disabled = false,
  readOnly = false,
  labels: labelOverrides,
  onUploadImage,
  maxImageBytes = 10 * 1024 * 1024,
  onStatusChange,
  isUrlAllowed = persistentUrlPolicy,
  children,
  className,
  ...props
}: MarkdownEditorRootProps & { engine: MarkdownEditorEngine | null }) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const markdown = value ?? internalValue;
  const [sourceMode, setSourceMode] = useState(false);
  const emitted = useRef(markdown);
  const labels = useMemo(() => ({ ...defaultMarkdownEditorLabels, ...labelOverrides }), [labelOverrides]);
  const snapshot = useEngineSnapshot(engine);
  const writable = !disabled && !readOnly;
  const source = sourceMode || snapshot.sourceRequired;
  const editable = engine !== null && writable && !(source && engine.sourceView === "textarea");
  const { cancelAll, ...imageUploads } = useImageUploads(engine, onUploadImage, maxImageBytes, isUrlAllowed, labels);

  function setMarkdown(next: string) {
    emitted.current = next;
    setInternalValue(next);
    onValueChange?.(next);
  }

  function upload(files: File[], position?: number) {
    if (writable) imageUploads.upload(files, position);
  }

  const emit = useEffectEvent(setMarkdown);
  const uploadFiles = useEffectEvent(upload);
  const cancelUploads = useEffectEvent(cancelAll);

  useEffect(() => engine?.onChange(emit), [engine]);

  useEffect(() => {
    engine?.setEditable(writable);
  }, [engine, writable]);

  useEffect(() => {
    if (!engine) return;
    if (emitted.current !== markdown) {
      emitted.current = markdown;
      cancelUploads();
    }
    engine.setMarkdown(markdown);
  }, [engine, markdown]);

  const canUpload = Boolean(onUploadImage);
  useEffect(() => {
    if (!engine || !canUpload) return;
    const element = engine.element;
    function paste(event: ClipboardEvent) {
      const files = filesOf(event.clipboardData);
      if (files.length === 0) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      uploadFiles(files);
    }
    function drop(event: DragEvent) {
      const files = filesOf(event.dataTransfer);
      if (files.length === 0) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      uploadFiles(files, engine?.positionAt({ x: event.clientX, y: event.clientY }) ?? undefined);
    }
    element.addEventListener("paste", paste, true);
    element.addEventListener("drop", drop, true);
    return () => {
      element.removeEventListener("paste", paste, true);
      element.removeEventListener("drop", drop, true);
    };
  }, [engine, canUpload]);

  const isEmpty = engine ? snapshot.isEmpty : markdown.trim() === "";
  const hasPendingUploads = imageUploads.uploads.length > 0;
  useEffect(() => {
    onStatusChange?.({ isEmpty, hasPendingUploads });
  }, [onStatusChange, isEmpty, hasPendingUploads]);

  return (
    <MarkdownEditorContext
      value={{
        engine,
        disabled,
        readOnly,
        editable,
        labels,
        source,
        markdown,
        sourceRequired: snapshot.sourceRequired,
        setSource: setSourceMode,
        setMarkdown,
        canUpload,
        isUrlAllowed,
        ...imageUploads,
        upload,
      }}
    >
      <div
        data-control-ui="markdown-editor"
        data-control-family="markdown-editor"
        data-slot="root"
        data-disabled={disabled ? "" : undefined}
        data-readonly={readOnly ? "" : undefined}
        className={cn("min-w-0", className)}
        {...props}
      >
        {children}
      </div>
    </MarkdownEditorContext>
  );
}

