import { PlusIcon } from "lucide-react";
import { type ReactNode, type RefObject, useRef, useState } from "react";
import { useSkinIcon } from "@/components/control-ui/skin-provider";
import { Button } from "@/components/control-ui/ui/button";
import { LiveStatus } from "@/components/control-ui/ui/live-status";
import { useMarkdownEditor } from "../context";
import type { MarkdownTableAxis } from "../engine";
import { canMoveLine, tableSize } from "./table-geometry";
import { TableGrip } from "./table-grip";
import { useTableTarget } from "./use-table-target";

export function MarkdownEditorTableControls({ container }: { container: RefObject<HTMLDivElement | null> }) {
  const PlusGlyph = useSkinIcon("plus", PlusIcon);
  const { engine, editable, labels } = useMarkdownEditor();
  const [menu, setMenu] = useState<MarkdownTableAxis | null>(null);
  const [dragging, setDragging] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const controls = useRef<HTMLDivElement>(null);
  const { target, layout, setHover } = useTableTarget(engine, container, controls, editable, menu !== null || dragging);
  const status = <LiveStatus key="status" message={announcement} />;
  if (!(engine && target && layout)) return <TableControlsFrame frame={controls}>{status}</TableControlsFrame>;
  const { tables } = engine;
  const { table } = target;
  const { rows, columns } = tableSize(table);
  const visibleLeft = Math.max(layout.table.left, layout.clip.left);
  const visibleRight = Math.min(layout.table.left + layout.table.width, layout.clip.left + layout.clip.width);

  function move(axis: MarkdownTableAxis, from: number, to: number) {
    if (!canMoveLine(axis === "row" ? rows : columns, axis, from, to) || !tables.move(table, axis, from, to)) return;
    setHover(tables.caret() ?? { table, row: target?.row ?? 0, column: target?.column ?? 0, [axis]: to });
    setAnnouncement(axis === "row" ? labels.rowMoved(to) : labels.columnMoved(to + 1));
  }

  const grip = (axis: MarkdownTableAxis) => (
    <TableGrip
      axis={axis}
      table={table}
      index={target[axis]}
      count={axis === "row" ? rows : columns}
      layout={layout}
      container={container}
      open={menu === axis}
      onOpenChange={(open) => setMenu(open ? axis : null)}
      onDraggingChange={setDragging}
      onMove={(from, to) => move(axis, from, to)}
    />
  );

  return (
    <TableControlsFrame frame={controls}>
      {grip("row")}
      {grip("column")}
      <Button
        type="button"
        variant="ghost"
        size="xs"
        className="absolute"
        data-markdown-table-add="row"
        aria-label={labels.addRow}
        style={{ top: layout.table.top + layout.table.height, left: visibleLeft, width: visibleRight - visibleLeft }}
        onClick={() => tables.append(table, "row")}
      >
        <PlusGlyph aria-hidden="true" />
      </Button>
      <Button
        type="button"
        variant="ghost"
        size="xs"
        className="absolute"
        data-markdown-table-add="column"
        aria-label={labels.addColumn}
        style={{ top: layout.table.top, left: visibleRight, height: layout.table.height }}
        onClick={() => tables.append(table, "column")}
      >
        <PlusGlyph aria-hidden="true" />
      </Button>
      {status}
    </TableControlsFrame>
  );
}

function TableControlsFrame({ frame, children }: { frame: RefObject<HTMLDivElement | null>; children: ReactNode }) {
  return (
    <div ref={frame} data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="table-controls">
      {children}
    </div>
  );
}

import type { MarkdownTableAxis, MarkdownTableTarget } from "../engine";

export type SurfaceBox = { top: number; left: number; width: number; height: number };
export type TableLayout = { table: SurfaceBox; clip: SurfaceBox; row: SurfaceBox; column: SurfaceBox };

/** The header row stays first: rows below it move, the header itself never does. */
export const firstMovable = (axis: MarkdownTableAxis) => (axis === "row" ? 1 : 0);

export function canMoveLine(count: number, axis: MarkdownTableAxis, from: number, to: number) {
  return from !== to && from >= firstMovable(axis) && to >= firstMovable(axis) && to < count;
}

export function tableSize(table: HTMLTableElement) {
  return { rows: table.rows.length, columns: table.rows[0]?.cells.length ?? 0 };
}

export function tableTargetAt(root: HTMLElement, node: EventTarget | null): MarkdownTableTarget | null {
  const cell = node instanceof Element ? node.closest("td, th") : null;
  const row = cell?.parentElement;
  const table = cell?.closest("table");
  if (!(cell instanceof HTMLTableCellElement && row instanceof HTMLTableRowElement && table && root.contains(table))) return null;
  return { table, row: row.rowIndex, column: cell.cellIndex };
}

export function measureTable(surface: HTMLElement, target: MarkdownTableTarget): TableLayout | null {
  const { table } = target;
  const row = table.rows[target.row];
  const head = table.rows[0]?.cells[target.column];
  if (!(table.isConnected && row && head)) return null;
  const origin = surface.getBoundingClientRect();
  const box = (rect: DOMRect): SurfaceBox => ({
    top: rect.top - origin.top + surface.scrollTop,
    left: rect.left - origin.left + surface.scrollLeft,
    width: rect.width,
    height: rect.height,
  });
  return {
    table: box(table.getBoundingClientRect()),
    clip: box((table.parentElement ?? table).getBoundingClientRect()),
    row: box(row.getBoundingClientRect()),
    column: box(head.getBoundingClientRect()),
  };
}

function edges(table: HTMLTableElement, axis: MarkdownTableAxis) {
  if (axis === "row") {
    const rows = Array.from(table.rows, (row) => row.getBoundingClientRect());
    return [...rows.map((rect) => rect.top), rows.at(-1)?.bottom ?? 0];
  }
  const cells = Array.from(table.rows[0]?.cells ?? [], (cell) => cell.getBoundingClientRect());
  return [...cells.map((rect) => rect.left), cells.at(-1)?.right ?? 0];
}

/** The gap a dragged row or column would land in; the header row's slot above it is never offered. */
export function nearestGap(table: HTMLTableElement, axis: MarkdownTableAxis, client: number) {
  const lines = edges(table, axis);
  const first = firstMovable(axis);
  let gap = first;
  for (let index = first; index < lines.length; index += 1) {
    if (Math.abs(client - (lines[index] ?? 0)) < Math.abs(client - (lines[gap] ?? 0))) gap = index;
  }
  return { gap, line: lines[gap] ?? 0 };
}

export function indexForGap(from: number, gap: number) {
  return gap > from ? gap - 1 : gap;
}

export function isNear(rect: DOMRect, x: number, y: number, reach: number) {
  return x > rect.left - reach && x < rect.right + reach && y > rect.top - reach && y < rect.bottom + reach;
}

export function toSurface(surface: HTMLElement, axis: MarkdownTableAxis, client: number) {
  const origin = surface.getBoundingClientRect();
  return axis === "row" ? client - origin.top + surface.scrollTop : client - origin.left + surface.scrollLeft;
}

"use client";

import { GripHorizontalIcon, GripVerticalIcon } from "lucide-react";
import { type PointerEvent as ReactPointerEvent, type RefObject, useRef, useState } from "react";
import { useSkinIcon } from "@/components/control-ui/skin-provider";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/control-ui/ui/dropdown-menu";
import { useMarkdownEditor } from "../context";
import type { MarkdownColumnAlign, MarkdownTableAxis } from "../engine";
import { firstMovable, indexForGap, nearestGap, type SurfaceBox, type TableLayout, toSurface } from "./table-geometry";

const DRAG_THRESHOLD = 4;
const MOVE_KEYS: Record<MarkdownTableAxis, [back: string, forward: string]> = {
  row: ["ArrowUp", "ArrowDown"],
  column: ["ArrowLeft", "ArrowRight"],
};

type Press = { pointerId: number; x: number; y: number; moved: boolean };
type TableGripProps = {
  axis: MarkdownTableAxis;
  table: HTMLTableElement;
  index: number;
  count: number;
  layout: TableLayout;
  container: RefObject<HTMLDivElement | null>;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDraggingChange: (dragging: boolean) => void;
  onMove: (from: number, to: number) => void;
};

function gripCenter(axis: MarkdownTableAxis, layout: TableLayout) {
  if (axis === "row") return { top: layout.row.top + layout.row.height / 2, left: Math.max(layout.table.left, layout.clip.left) };
  return { top: layout.table.top, left: layout.column.left + layout.column.width / 2 };
}

const withinClip = (left: number, clip: SurfaceBox) => left >= clip.left && left <= clip.left + clip.width;

export function TableGrip({ axis, table, index, count, layout, container, open, onOpenChange, onDraggingChange, onMove }: TableGripProps) {
  const GripVerticalGlyph = useSkinIcon("gripVertical", GripVerticalIcon);
  const GripHorizontalGlyph = useSkinIcon("gripHorizontal", GripHorizontalIcon);
  const { engine, labels } = useMarkdownEditor();
  const [dropLine, setDropLine] = useState<{ gap: number; at: number } | null>(null);
  const press = useRef<Press | null>(null);
  const swallowClick = useRef(false);
  const openAtPress = useRef(false);
  const popup = useRef<HTMLDivElement>(null);
  const center = gripCenter(axis, layout);
  const movable = index >= firstMovable(axis);
  if (!engine || (axis === "column" && !withinClip(center.left, layout.clip))) return null;
  const { tables } = engine;

  function startPress(event: ReactPointerEvent<HTMLButtonElement>) {
    if (event.button !== 0) return;
    openAtPress.current = open;
    press.current = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, moved: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function beginDrag(current: Press, event: ReactPointerEvent<HTMLButtonElement>) {
    if (!movable || Math.hypot(event.clientX - current.x, event.clientY - current.y) < DRAG_THRESHOLD) return false;
    current.moved = true;
    onOpenChange(false);
    onDraggingChange(true);
    tables.select(table, axis, index);
    return true;
  }

  function dragPress(event: ReactPointerEvent<HTMLButtonElement>) {
    const current = press.current;
    const surface = container.current;
    if (!(current && surface) || current.pointerId !== event.pointerId) return;
    if (!(current.moved || beginDrag(current, event))) return;
    const client = axis === "row" ? event.clientY : event.clientX;
    const { gap, line } = nearestGap(table, axis, client);
    setDropLine({ gap, at: toSurface(surface, axis, line) });
  }

  function endPress(event: ReactPointerEvent<HTMLButtonElement>) {
    const current = press.current;
    if (!current || current.pointerId !== event.pointerId) return;
    press.current = null;
    swallowClick.current = current.moved;
    if (current.moved && dropLine) onMove(index, indexForGap(index, dropLine.gap));
    if (current.moved) onDraggingChange(false);
    setDropLine(null);
  }

  function cancelPress() {
    if (press.current?.moved) onDraggingChange(false);
    press.current = null;
    setDropLine(null);
  }

  function click() {
    const dragged = swallowClick.current;
    const wasOpen = openAtPress.current;
    swallowClick.current = false;
    openAtPress.current = false;
    if (dragged) return;
    if (!wasOpen) tables.select(table, axis, index);
    onOpenChange(!wasOpen);
  }

  function editorIfFocusIsLost() {
    const active = document.activeElement;
    const lost = !active || active === document.body || popup.current?.contains(active) === true;
    return lost && engine ? engine.element : false;
  }

  const [back, forward] = MOVE_KEYS[axis];
  const visibleLeft = Math.max(layout.table.left, layout.clip.left);
  const visibleRight = Math.min(layout.table.left + layout.table.width, layout.clip.left + layout.clip.width);

  return (
    <>
      <DropdownMenu
        open={open}
        onOpenChange={(next, details) => {
          if (details.reason === "trigger-press") return;
          if (next && details.event instanceof KeyboardEvent && details.event.altKey) return;
          onOpenChange(next);
        }}
      >
        <DropdownMenuTrigger
          variant="surface"
          size="xs"
          iconOnly
          className="absolute"
          data-markdown-table-grip={axis}
          data-dragging={dropLine ? "" : undefined}
          aria-label={axis === "row" ? labels.rowActions : labels.columnActions}
          aria-description={labels.tableGripDescription}
          style={center}
          onPointerDown={startPress}
          onPointerMove={dragPress}
          onPointerUp={endPress}
          onPointerCancel={cancelPress}
          onClick={click}
          onKeyDown={(event) => {
            if (!(event.altKey && (event.key === back || event.key === forward))) return;
            event.preventDefault();
            onMove(index, index + (event.key === back ? -1 : 1));
          }}
        >
          {axis === "row" ? <GripVerticalGlyph aria-hidden="true" /> : <GripHorizontalGlyph aria-hidden="true" />}
        </DropdownMenuTrigger>
        <DropdownMenuContent ref={popup} side={axis === "row" ? "left" : "top"} align="start" finalFocus={editorIfFocusIsLost}>
          <TableGripMenu axis={axis} table={table} index={index} count={count} onMove={onMove} />
        </DropdownMenuContent>
      </DropdownMenu>
      {dropLine ? (
        <div
          data-control-ui="markdown-editor"
          data-control-family="markdown-editor"
          data-slot="table-drop-line"
          data-axis={axis}
          style={
            axis === "row"
              ? { top: dropLine.at, left: visibleLeft, width: visibleRight - visibleLeft }
              : { left: dropLine.at, top: layout.table.top, height: layout.table.height }
          }
        />
      ) : null}
    </>
  );
}

type TableGripMenuProps = Pick<TableGripProps, "axis" | "table" | "index" | "count" | "onMove">;

function TableGripMenu({ axis, table, index, count, onMove }: TableGripMenuProps) {
  const { engine, labels } = useMarkdownEditor();
  if (!engine) return null;
  const { tables } = engine;
  const header = axis === "row" && index === 0;
  const insert = (side: "before" | "after") => () => tables.insert(table, axis, index, side);
  const align = (value: MarkdownColumnAlign) => () => tables.align(table, index, value);

  return (
    <>
      {axis === "row" ? (
        <>
          <DropdownMenuItem disabled={header} onClick={insert("before")}>
            {labels.insertRowAbove}
          </DropdownMenuItem>
          <DropdownMenuItem onClick={insert("after")}>{labels.insertRowBelow}</DropdownMenuItem>
        </>
      ) : (
        <>
          <DropdownMenuItem onClick={insert("before")}>{labels.insertColumnLeft}</DropdownMenuItem>
          <DropdownMenuItem onClick={insert("after")}>{labels.insertColumnRight}</DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem onClick={align("left")}>{labels.alignLeft}</DropdownMenuItem>
          <DropdownMenuItem onClick={align("center")}>{labels.alignCenter}</DropdownMenuItem>
          <DropdownMenuItem onClick={align("right")}>{labels.alignRight}</DropdownMenuItem>
        </>
      )}
      <DropdownMenuSeparator />
      <DropdownMenuItem disabled={header || index === firstMovable(axis)} onClick={() => onMove(index, index - 1)}>
        {axis === "row" ? labels.moveRowUp : labels.moveColumnLeft}
      </DropdownMenuItem>
      <DropdownMenuItem disabled={header || index === count - 1} onClick={() => onMove(index, index + 1)}>
        {axis === "row" ? labels.moveRowDown : labels.moveColumnRight}
      </DropdownMenuItem>
      <DropdownMenuSeparator />
      <DropdownMenuItem tone="danger" disabled={axis === "row" ? header : count === 1} onClick={() => tables.remove(table, axis, index)}>
        {axis === "row" ? labels.deleteRow : labels.deleteColumn}
      </DropdownMenuItem>
    </>
  );
}

"use client";

import { type Dispatch, type RefObject, type SetStateAction, useEffect, useLayoutEffect, useRef, useState } from "react";
import type { MarkdownEditorEngine, MarkdownTableTarget } from "../engine";
import { isNear, measureTable, type TableLayout, tableSize, tableTargetAt } from "./table-geometry";

const HOVER_REACH = 28;

const sameTarget = (a: MarkdownTableTarget | null, b: MarkdownTableTarget | null) =>
  a === b || (a !== null && b !== null && a.table === b.table && a.row === b.row && a.column === b.column);

function hoverFor(root: HTMLElement, current: MarkdownTableTarget | null, event: MouseEvent) {
  const next = tableTargetAt(root, event.target);
  if (next) return sameTarget(current, next) ? current : next;
  const rect = current?.table.isConnected ? current.table.getBoundingClientRect() : undefined;
  return rect && isNear(rect, event.clientX, event.clientY, HOVER_REACH) ? current : null;
}

type TableTargetState = {
  target: MarkdownTableTarget | null;
  layout: TableLayout | null;
  setHover: Dispatch<SetStateAction<MarkdownTableTarget | null>>;
};

/** The table cell the controls attach to: the hovered cell, else the caret's cell while editing or while a grip is held. */
export function useTableTarget(
  engine: MarkdownEditorEngine | null,
  container: RefObject<HTMLDivElement | null>,
  controls: RefObject<HTMLDivElement | null>,
  enabled: boolean,
  holding: boolean,
): TableTargetState {
  const [hover, setHover] = useState<MarkdownTableTarget | null>(null);
  const [revision, setRevision] = useState(0);
  const [layout, setLayout] = useState<TableLayout | null>(null);
  const holdingRef = useRef(holding);
  holdingRef.current = holding;

  useEffect(() => {
    const surface = container.current;
    if (!engine || !surface || !enabled) return;
    let frame = 0;
    let latest: MouseEvent | null = null;
    const insideControls = (node: unknown) => node instanceof Node && controls.current?.contains(node) === true;
    function follow(event: MouseEvent) {
      if (holdingRef.current || insideControls(event.target) || !engine) return;
      setHover((current) => hoverFor(engine.element, current, event));
    }
    function track(event: MouseEvent) {
      latest = event;
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        if (latest) follow(latest);
      });
    }
    function leave() {
      if (!(holdingRef.current || insideControls(document.activeElement))) setHover(null);
    }
    function remeasure() {
      setRevision((value) => value + 1);
    }
    function engineChanged() {
      setHover((current) => (current && !current.table.isConnected ? null : current));
      remeasure();
    }
    surface.addEventListener("mousemove", track);
    surface.addEventListener("mouseleave", leave);
    surface.addEventListener("scroll", remeasure, { capture: true, passive: true });
    window.addEventListener("resize", remeasure);
    const unsubscribe = engine.subscribe(engineChanged);
    return () => {
      cancelAnimationFrame(frame);
      unsubscribe();
      surface.removeEventListener("mousemove", track);
      surface.removeEventListener("mouseleave", leave);
      surface.removeEventListener("scroll", remeasure, { capture: true });
      window.removeEventListener("resize", remeasure);
    };
  }, [engine, container, controls, enabled]);

  const live = engine !== null && enabled;
  const caret = live && (engine.getSnapshot().focused || holding) ? engine.tables.caret() : null;
  const found = live ? (hover ?? caret) : null;
  const size = found?.table.isConnected ? tableSize(found.table) : null;
  const target =
    found && size
      ? { table: found.table, row: Math.min(found.row, size.rows - 1), column: Math.min(found.column, size.columns - 1) }
      : null;
  const table = target?.table;
  const row = target?.row;
  const column = target?.column;

  // biome-ignore lint/correctness/useExhaustiveDependencies: revision re-measures after scroll, resize and edits
  useLayoutEffect(() => {
    const surface = container.current;
    if (!(surface && table && row !== undefined && column !== undefined)) {
      setLayout(null);
      return;
    }
    setLayout(measureTable(surface, { table, row, column }));
  }, [container, table, row, column, revision]);

  return { target: layout ? target : null, layout, setHover };
}

